            "id": "143871",
            "title": "Our Mission - Office Hours",
            "alias": "our-mission-office-hours",
            "categoryId": "147",
            "categoryTitle": "- - Homepage Articles (School)",
            "introtext": "\t<div class=\"mission-hours\">\n<div class=\"mission-box\">\n<h2>Our Mission</h2>\n<p>Because we love Jesus, St. Joseph Catholic School serves all students and provides a Christ-centered educational environment where love of God inspires everything we do, think, say, feel, and become.</p>\n</div>\n<div class=\"hours-box\">\n<h2>Office Hours</h2>\n<p>Monday-Friday<br />7:30 a.m. - 3:30 p.m.</p>\n</div>\n</div>",
            "fulltext": "",
            "state": "1",
            "access": "1"
          }
        ]
      },
