          {
            "id": "143874",
            "title": "Enrolling New Families",
            "alias": "enrolling-new-families",
            "categoryId": "147",
            "categoryTitle": "- - Homepage Articles (School)",
            "introtext": "\t<div class=\"enroll-widget-wrapper widget-wrapper\">\n<div class=\"widget-title\">\n<h3 class=\"g-title\">Enrolling New Families</h3>\n</div>\n<div class=\"widget-feed\">\n<div class=\"widget-feed-inner-box\">\n<div class=\"widget-feed-image\"><img src=\"images/template/school26/enrolling.jpg\" alt=\"\" /></div>\n<div class=\"widget-feed-text\">\n<p class=\"ital-text\">Shelby Catholic School welcomes families seeking a faith-centered, academically strong education rooted in Catholic tradition.</p>\n<p>Click below to begin the enrollment process for the upcoming school year.</p>\n</div>\n</div>\n</div>\n<div class=\"widget-button\"><a class=\"button\" href=\"new-families-cl/registration\">Enroll Now</a></div>\n</div>",
            "fulltext": "",
            "state": "1",
            "access": "1"
          }
        ]
      },
      {
        "particleId": "contentarray-6583",
        "particleTitle": "Facebook",
        "particleType": "contentarray",
