            "categoryId": "147",
            "categoryTitle": "- - Homepage Articles (School)",
            "introtext": "\t<div class=\"footer-wrapper\">\n<div class=\"holy-art-box\">\n<p><a href=\"https://www.holyart.com/\" target=\"_blank\" rel=\"noopener noreferrer\">HolyArt.com</a> is a proud sponsor of this parish website.</p>\n</div>\n<div class=\"footer-content-row\">\n<div class=\"footer-content-column\">\n<div class=\"footer-logo\"><a href=\"school\"><img src=\"images/template/school26/logo.png\" alt=\"School Logo\" /></a></div>\n<div class=\"footer-text\">\n<h1><a href=\"school\">St. Joseph Catholic School</a></h1>\n<p><a href=\"about-sjcs-cl/contact\">127 E. Broadway St. Shelbyville, IN 46176</a><br />Phone: <a href=\"tel:3173984202\" target=\"_blank\" rel=\"noopener noreferrer\">317-398-4202</a> | <a href=\"mailto:office@sjsshelbyville.org\" target=\"_blank\" rel=\"noopener noreferrer\">office@sjsshelbyville.org</a></p>\n</div>\n</div>\n<div class=\"footer-social-icons\">{loadmoduleid 200}</div>\n</div>\n</div>",
